This React component is supposed to show search results as the user types, but it fires a request on every keystroke and sometimes shows results for an older query after a newer one. What's wrong and how do I fix it?

import { useState, useEffect } from 'react';

export default function Search() {
  const [q, setQ] = useState('');
  const [results, setResults] = useState([]);

  useEffect(() => {
    if (!q) return;
    fetch(`/api/search?q=${q}`)
      .then(r => r.json())
      .then(data => setResults(data.items));
  }, [q]);

  return (
    <div>
      <input value={q} onChange={e => setQ(e.target.value)} placeholder="Search..." />
      <ul>
        {results.map(item => <li>{item.title}</li>)}
      </ul>
    </div>
  );
}

